  position           INTEGER NOT NULL,
  filed_at           INTEGER NOT NULL,
  by_kind            TEXT NOT NULL CHECK (by_kind IN ('player','org')),
  by_id              TEXT NOT NULL,
  by_name            TEXT NOT NULL CHECK (length(by_name) <= 200),
  reason             TEXT NOT NULL CHECK (length(reason) <= 300),
